'use strict';

const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const Vault = require('./zoho-vault-crypto.cjs');

const passphrase = 'correct horse battery staple';
const salt = '0123456789abcdef0123456789abcdef';
const iterations = 1000;
const expectedMasterKey = '6d7a97b88c72c212974d28d42438240dd98a1d2b62950fd9f8fa403fbe490588';
const masterKey = Vault.PBKDF2_key(passphrase, salt, iterations);
assert.equal(masterKey, expectedMasterKey);

// Generated by Zoho's original Zohovault.AES.encrypt from the verified npm
// package, with Date fixed to 1700000000123 and Math.random fixed to 0.5.
const officialCiphertext = 'ewD/fwDxU2XcXwdry6GdoFAPWO0kclWG+oJFrP8fMxcDURIxpDKjiMwrJg==';
const plaintext = 'synthetic-user@example.test\nS3cret!';
assert.equal(Vault.decrypt(officialCiphertext, masterKey), plaintext);

// The corresponding official 8-byte nonce was 7b00ff7f00f15365.
assert.equal(
  Vault.encrypt(plaintext, masterKey, { nonce: Buffer.from('7b00ff7f00f15365', 'hex') }),
  officialCiphertext,
);

assert.equal(
  Vault.hash('abc'),
  'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad',
);

// Synthetic RSA-4096 OAEP/SHA-256 round trip.
const rsa4096 = crypto.generateKeyPairSync('rsa', {
  modulusLength: 4096,
  publicExponent: 0x10001,
});
const orgKey = 'synthetic-org-key-32-chars-1234';
const rsa4096Ciphertext = crypto.publicEncrypt(
  {
    key: rsa4096.publicKey,
    padding: crypto.constants.RSA_PKCS1_OAEP_PADDING,
    oaepHash: 'sha256',
  },
  Buffer.from(orgKey, 'utf8'),
).toString('base64');
const rsa4096PrivateKey = rsa4096.privateKey.export({
  format: 'der',
  type: 'pkcs8',
}).toString('base64');
assert.equal(Vault.RSA_decrypt(rsa4096Ciphertext, rsa4096PrivateKey, 'RSA_4096'), orgKey);

// Synthetic legacy RSA-1024 PKCS#1 v1.5 round trip.
const rsa1024 = crypto.generateKeyPairSync('rsa', {
  modulusLength: 1024,
  publicExponent: 0x10001,
});
const legacyCiphertext = crypto.publicEncrypt(
  { key: rsa1024.publicKey, padding: crypto.constants.RSA_PKCS1_PADDING },
  Buffer.from('legacy-org-key', 'utf8'),
).toString('hex');
const jwk = rsa1024.privateKey.export({ format: 'jwk' });
const toHex = (value) => Buffer.from(value, 'base64url').toString('hex');
const legacyPrivateKey = [jwk.n, jwk.e, jwk.d, jwk.p, jwk.q, jwk.dp, jwk.dq, jwk.qi]
  .map(toHex)
  .join(',');
assert.equal(Vault.RSA_decrypt(legacyCiphertext, legacyPrivateKey, 'RSA_1024'), 'legacy-org-key');

console.log('All Zoho Vault compatibility tests passed.');
